"""Loader for the official-backend API key + secret pair."""

from __future__ import annotations

import os
from dataclasses import dataclass


@dataclass(frozen=True)
class ApiKeyAuth:
    api_key: str
    secret: str

    @property
    def header(self) -> str:
        return f"Key {self.api_key}:{self.secret}"

    @property
    def v1_headers(self) -> dict[str, str]:
        """Legacy /v1/ routes authenticate with split headers, not the Key scheme."""
        return {"hf-api-key": self.api_key, "hf-secret": self.secret}


class MissingCredentialsError(RuntimeError):
    """Raised when the official backend is invoked without credentials."""


def load_from_env() -> ApiKeyAuth:
    key = os.getenv("HIGGSFIELD_API_KEY")
    secret = os.getenv("HIGGSFIELD_SECRET")
    if not key or not secret:
        raise MissingCredentialsError(
            "HIGGSFIELD_API_KEY and HIGGSFIELD_SECRET must be set to use the official backend. "
            "Get credentials from https://platform.higgsfield.ai/."
        )
    return ApiKeyAuth(api_key=key, secret=secret)

"""Official backend driver: ``platform.higgsfield.ai``.

API shape (https://docs.higgsfield.ai/how-to/introduction.md):

* ``POST /{model_id}`` -> ``{ request_id, status_url, cancel_url, ... }``
* ``GET  /requests/{request_id}/status`` -> status payload
* ``POST /requests/{request_id}/cancel``

Auth is a single header: ``Authorization: Key {api_key}:{secret}``.
"""

from __future__ import annotations

from typing import Any, cast

import httpx

from higgsfield_mcp.auth.api_key import ApiKeyAuth, load_from_env
from higgsfield_mcp.errors import NetworkError, SchemaError, classify_http
from higgsfield_mcp.models import Backend as BackendName
from higgsfield_mcp.models import ModelSpec
from higgsfield_mcp.reliability import CircuitBreaker, new_idempotency_key, retrying_request

from .base import BackendDriver, BackendError, JobHandle, JobState, JobStatus

BASE_URL = "https://platform.higgsfield.ai"

_STATE_MAP: dict[str, JobState] = {
    "queued": "queued",
    "in_progress": "in_progress",
    "running": "in_progress",
    "processing": "in_progress",
    "completed": "completed",
    "succeeded": "completed",
    "failed": "failed",
    "error": "failed",
    "nsfw": "nsfw",
    "cancelled": "cancelled",
    "canceled": "cancelled",
}


class OfficialBackend(BackendDriver):
    name: BackendName = "official"

    def __init__(self, *, auth: ApiKeyAuth | None = None, base_url: str = BASE_URL) -> None:
        self._auth = auth or load_from_env()
        self._base_url = base_url
        self._client = httpx.AsyncClient(
            base_url=base_url,
            headers={
                "Authorization": self._auth.header,
                "Accept": "application/json",
                "Content-Type": "application/json",
            },
            timeout=httpx.Timeout(30.0, connect=10.0),
        )
        self._breaker = CircuitBreaker()

    async def aclose(self) -> None:
        await self._client.aclose()

    async def submit(self, model: ModelSpec, params: dict[str, Any]) -> JobHandle:
        if model.backend != "official":
            raise BackendError(f"OfficialBackend cannot submit web model {model.id!r}")
        self._breaker.check()
        idem = new_idempotency_key()

        async def _send() -> httpx.Response:
            try:
                return await self._client.post(
                    f"/{model.endpoint}", json=params, headers={"X-Idempotency-Key": idem}
                )
            except httpx.HTTPError as exc:
                raise NetworkError(str(exc)) from exc

        try:
            resp = cast(httpx.Response, await retrying_request(_send))
        except Exception:
            self._breaker.record_failure()
            raise
        if resp.status_code >= 500:
            self._breaker.record_failure()
        else:
            self._breaker.record_success()
        body = self._json_or_raise(resp)
        request_id = body.get("request_id") or body.get("id")
        if not request_id:
            raise SchemaError(
                f"Submit response missing request_id: {body!r}",
                status_code=resp.status_code,
            )
        return JobHandle(backend="official", request_id=request_id)

    async def status(self, handle: JobHandle) -> JobStatus:
        self._breaker.check()

        async def _send() -> httpx.Response:
            try:
                return await self._client.get(f"/requests/{handle.request_id}/status")
            except httpx.HTTPError as exc:
                raise NetworkError(str(exc)) from exc

        try:
            resp = cast(httpx.Response, await retrying_request(_send, max_attempts=3))
        except Exception:
            self._breaker.record_failure()
            raise
        if resp.status_code >= 500:
            self._breaker.record_failure()
        else:
            self._breaker.record_success()
        body = self._json_or_raise(resp)
        raw_state = str(body.get("status", "")).lower()
        state = _STATE_MAP.get(raw_state, "in_progress")
        images = tuple(self._extract_image_urls(body))
        video_url = self._extract_video_url(body)
        return JobStatus(
            state=state,
            progress=body.get("progress"),
            images=images,
            video_url=video_url,
            error=body.get("error") or body.get("error_message"),
            raw=body,
        )

    async def cancel(self, handle: JobHandle) -> None:
        resp = await self._client.post(f"/requests/{handle.request_id}/cancel")
        if resp.status_code >= 400:
            raise BackendError(
                f"Cancel failed: {resp.status_code}",
                status_code=resp.status_code,
                body=resp.text,
            )

    async def upload(self, data: bytes, mime: str) -> str:
        resp = await self._client.post("/files/generate-upload-url", json={"content_type": mime})
        body = self._json_or_raise(resp)
        upload_url = body.get("upload_url")
        public_url = body.get("public_url") or body.get("url")
        if not upload_url or not public_url:
            raise BackendError(
                f"generate-upload-url response missing upload_url/public_url: {body!r}",
                status_code=resp.status_code,
            )
        # The signed PUT must NOT carry the platform Authorization header.
        async with httpx.AsyncClient(timeout=httpx.Timeout(120.0, connect=10.0)) as raw:
            put = await raw.put(upload_url, content=data, headers={"Content-Type": mime})
            if put.status_code >= 400:
                raise BackendError(
                    f"Signed upload PUT failed: HTTP {put.status_code}",
                    status_code=put.status_code,
                    body=put.text,
                )
        return str(public_url)

    async def _v1_request(
        self, method: str, path: str, *, json: dict[str, Any] | None = None
    ) -> Any:
        """Call a legacy /v1/ (or /agents/) endpoint with hf-api-key/hf-secret auth.

        A dedicated client is used so the v2 ``Key`` Authorization default is not sent.
        Response shapes are undocumented; callers parse defensively.
        """
        headers = {
            **self._auth.v1_headers,
            "Accept": "application/json",
            "Content-Type": "application/json",
        }
        self._breaker.check()
        async with httpx.AsyncClient(
            base_url=self._base_url, timeout=httpx.Timeout(60.0, connect=10.0)
        ) as client:

            async def _send() -> httpx.Response:
                try:
                    return await client.request(method, path, json=json, headers=headers)
                except httpx.HTTPError as exc:
                    raise NetworkError(str(exc)) from exc

            try:
                resp = cast(httpx.Response, await retrying_request(_send, max_attempts=3))
            except Exception:
                self._breaker.record_failure()
                raise
        if resp.status_code >= 500:
            self._breaker.record_failure()
        else:
            self._breaker.record_success()
        if resp.status_code >= 400:
            raise classify_http(resp.status_code, resp.text, dict(resp.headers))
        try:
            return resp.json()
        except ValueError as exc:
            raise BackendError(f"Invalid JSON response: {resp.text[:200]}") from exc

    @staticmethod
    def _character_view(raw: dict[str, Any]) -> dict[str, Any]:
        images = raw.get("image_urls") or raw.get("images") or raw.get("medias") or []
        return {
            "id": raw.get("id") or raw.get("custom_reference_id") or raw.get("soul_id") or "",
            "name": raw.get("name") or raw.get("title") or "",
            "status": str(raw.get("status") or raw.get("state") or "unknown"),
            "image_count": len(images) if isinstance(images, list) else 0,
            "raw": raw,
        }

    async def create_character(self, name: str, image_urls: list[str]) -> dict[str, Any]:
        body = self._v1_payload_create(name, image_urls)
        raw = await self._v1_request("POST", "/v1/custom-references", json=body)
        return self._character_view(raw if isinstance(raw, dict) else {"raw": raw})

    @staticmethod
    def _v1_payload_create(name: str, image_urls: list[str]) -> dict[str, Any]:
        # Request shape is a best guess (CLI says 5-20 training images).
        return {"name": name, "image_urls": list(image_urls)}

    async def get_character(self, character_id: str) -> dict[str, Any]:
        raw = await self._v1_request("GET", f"/v1/custom-references/{character_id}")
        return self._character_view(raw if isinstance(raw, dict) else {"raw": raw})

    async def list_characters(self, page: int = 1, page_size: int = 50) -> dict[str, Any]:
        raw = await self._v1_request(
            "GET", f"/v1/custom-references/list?page={page}&page_size={page_size}"
        )
        items: list[Any] = []
        if isinstance(raw, dict):
            for key in ("items", "results", "custom_references", "data"):
                v = raw.get(key)
                if isinstance(v, list):
                    items = v
                    break
        elif isinstance(raw, list):
            items = raw
        chars = [self._character_view(i) for i in items if isinstance(i, dict)]
        return {"count": len(chars), "characters": chars}

    async def delete_character(self, character_id: str) -> dict[str, Any]:
        await self._v1_request("DELETE", f"/v1/custom-references/{character_id}")
        return {"deleted": True, "character_id": character_id}

    @staticmethod
    def _names_view(raw: Any) -> dict[str, Any]:
        names: list[str] = []
        seq: list[Any] = []
        if isinstance(raw, list):
            seq = raw
        elif isinstance(raw, dict):
            for key in ("styles", "motions", "items", "results", "data"):
                v = raw.get(key)
                if isinstance(v, list):
                    seq = v
                    break
        for entry in seq:
            if isinstance(entry, str):
                names.append(entry)
            elif isinstance(entry, dict):
                n = entry.get("name") or entry.get("id") or entry.get("slug")
                if n:
                    names.append(str(n))
        return {"count": len(names), "names": names, "raw": raw if isinstance(raw, dict) else {}}

    async def get_balance(self) -> dict[str, Any]:
        raw = await self._v1_request("POST", "/v1/billing/credits", json={})
        d = raw if isinstance(raw, dict) else {}
        credits = d.get("credits")
        if credits is None:
            credits = d.get("balance") or d.get("available_credits")
        return {"credits": credits, "plan": d.get("plan") or d.get("tier"), "raw": d}

    async def list_jobs_official(self, page: int = 1, page_size: int = 20) -> dict[str, Any]:
        raw = await self._v1_request(
            "POST", "/agents/jobs", json={"page": page, "page_size": page_size}
        )
        jobs: list[Any] = []
        if isinstance(raw, dict):
            for key in ("jobs", "items", "results", "job_sets", "data"):
                v = raw.get(key)
                if isinstance(v, list):
                    jobs = v
                    break
        elif isinstance(raw, list):
            jobs = raw
        return {"count": len(jobs), "jobs": [j for j in jobs if isinstance(j, dict)]}

    async def list_soul_styles(self) -> dict[str, Any]:
        return self._names_view(await self._v1_request("GET", "/v1/text2image/soul-styles"))

    async def list_motions(self) -> dict[str, Any]:
        return self._names_view(await self._v1_request("GET", "/v1/motions"))

    async def speak(self, image_url: str, audio_url: str, prompt: str | None = None) -> JobHandle:
        body: dict[str, Any] = {"input_image_url": image_url, "audio_url": audio_url}
        if prompt:
            body["prompt"] = prompt
        raw = await self._v1_request("POST", "/v1/speak/higgsfield", json=body)
        d = raw if isinstance(raw, dict) else {}
        request_id = d.get("request_id") or d.get("id") or d.get("job_id")
        if not request_id:
            raise SchemaError(f"speak response missing request_id: {d!r}")
        return JobHandle(backend="official", request_id=str(request_id))

    @staticmethod
    def _extract_image_urls(body: dict[str, Any]) -> list[str]:
        images = body.get("images") or []
        out: list[str] = []
        for entry in images:
            if isinstance(entry, str):
                out.append(entry)
            elif isinstance(entry, dict):
                url = entry.get("url") or entry.get("image_url")
                if url:
                    out.append(url)
        return out

    @staticmethod
    def _extract_video_url(body: dict[str, Any]) -> str | None:
        video = body.get("video")
        if isinstance(video, str):
            return video
        if isinstance(video, dict):
            return video.get("url")
        return None

    @staticmethod
    def _json_or_raise(resp: httpx.Response) -> dict[str, Any]:
        if resp.status_code >= 400:
            raise classify_http(resp.status_code, resp.text, dict(resp.headers))
        try:
            data: dict[str, Any] = resp.json()
        except ValueError as exc:
            raise BackendError(f"Invalid JSON response: {resp.text[:200]}") from exc
        return data

"""MCP resources exposing the model catalog.

``higgsfield://models`` returns the full catalog (including inferred models);
``higgsfield://models/{kind}`` filters by kind. Clients that support resources
can subscribe to the catalog instead of calling list_models repeatedly.
"""

from __future__ import annotations

from typing import Any, cast, get_args

from fastmcp import FastMCP

from higgsfield_mcp.models import Kind
from higgsfield_mcp.tools import list_models

_KINDS = get_args(Kind)  # stays in sync with the Kind literal


def register_resources(mcp: FastMCP) -> None:
    @mcp.resource("higgsfield://models")
    async def all_models() -> dict[str, Any]:
        """The full Higgsfield model catalog, including inferred (unverified) models."""
        return await list_models(include_unverified=True)

    @mcp.resource("higgsfield://models/{kind}")
    async def models_by_kind(kind: str) -> dict[str, Any]:
        """Models of a single kind: image, video, or speech."""
        if kind not in _KINDS:
            return {"count": 0, "models": [], "error": f"unknown kind: {kind!r}"}
        return await list_models(kind=cast(Kind, kind), include_unverified=True)

"""MCP prompt templates for common Higgsfield generation intents.

These are reusable, parameterized prompt scaffolds a client can fetch and feed
into ``generate_image`` / ``generate_video``. Exposing prompts is something the
hosted MCP does not do for clients.
"""

from __future__ import annotations

from fastmcp import FastMCP


def register_prompts(mcp: FastMCP) -> None:
    @mcp.prompt
    def cinematic_shot(subject: str, mood: str = "dramatic", lens: str = "anamorphic") -> str:
        """A cinematic still/video prompt for a subject with a given mood and lens."""
        return (
            f"Cinematic shot of {subject}. {mood} lighting, {lens} lens, shallow depth of field, "
            "filmic color grade, volumetric light, 35mm grain, composed with the rule of thirds."
        )

    @mcp.prompt
    def product_360(product: str, surface: str = "matte studio backdrop") -> str:
        """A turntable product-showcase prompt."""
        return (
            f"Studio product showcase of {product} on a {surface}, slow 360-degree turntable, "
            "soft key light with rim highlight, crisp reflections, high detail, commercial photography."
        )

    @mcp.prompt
    def animate_portrait(subject: str, motion: str = "subtle head turn and natural blink") -> str:
        """An image-to-video prompt to gently animate a portrait."""
        return (
            f"Animate this portrait of {subject}: {motion}, breathing motion, soft ambient light shift, "
            "preserve identity and facial features, photoreal, smooth natural motion."
        )

    @mcp.prompt
    def action_sequence(subject: str, action: str, setting: str = "urban environment") -> str:
        """A dynamic action video prompt."""
        return (
            f"Dynamic action sequence: {subject} {action} in a {setting}. Fast camera movement, "
            "motion blur, dramatic angles, high energy, cinematic pacing, detailed environment."
        )

    @mcp.prompt
    def b_roll(scene: str, style: str = "documentary") -> str:
        """An atmospheric b-roll video prompt."""
        return (
            f"Atmospheric {style} b-roll of {scene}. Slow, steady camera movement, natural light, "
            "rich texture and depth, ambient mood, color-graded for {style} tone."
        )

"""Structured error taxonomy for backend failures.

Each subclass maps a class of HTTP/transport failure to an actionable message.
``classify_http`` turns a raw HTTP failure into the right typed error so callers
(and the retry layer) can branch on type instead of parsing strings.
"""

from __future__ import annotations

from collections.abc import Mapping

from higgsfield_mcp.backends.base import BackendError


class AuthError(BackendError):
    """401/403 with no bot-challenge signal: credentials are missing or invalid."""


class RateLimitError(BackendError):
    """429: too many requests. ``retry_after`` is seconds from the Retry-After header."""

    def __init__(
        self,
        message: str,
        *,
        retry_after: float | None = None,
        status_code: int | None = None,
        body: str | None = None,
    ) -> None:
        super().__init__(message, status_code=status_code, body=body)
        self.retry_after = retry_after


class BotChallengeError(BackendError):
    """403 Cloudflare managed challenge (TLS fingerprint). Not an auth problem."""


class SchemaError(BackendError):
    """2xx response whose body is missing required fields (e.g. no job id)."""


class NetworkError(BackendError):
    """Transport-level failure (connection reset, timeout, DNS)."""


class CircuitOpenError(BackendError):
    """The circuit breaker is open: the backend is failing and is cooling down."""


def parse_retry_after(value: str | None) -> float | None:
    """Parse a Retry-After header value in delta-seconds form. HTTP-date form is ignored."""
    if value is None:
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def classify_http(
    status_code: int,
    body: str | None = None,
    headers: Mapping[str, str] | None = None,
) -> BackendError:
    """Map an HTTP failure to a typed error."""
    headers = headers or {}
    text = (body or "")[:500]
    lower_headers = {k.lower(): v for k, v in headers.items()}

    if status_code == 403:
        cf = str(lower_headers.get("cf-mitigated", "")).lower()
        if "challenge" in cf or "just a moment" in text.lower():
            return BotChallengeError(
                "Cloudflare TLS-fingerprint challenge (HTTP 403). "
                "Upgrade curl-cffi or retry later from a residential IP.",
                status_code=status_code,
                body=text,
            )
    if status_code in (401, 403):
        return AuthError(
            f"Authentication failed (HTTP {status_code}). Check credentials. {text}",
            status_code=status_code,
            body=text,
        )
    if status_code == 429:
        return RateLimitError(
            "Rate limited (HTTP 429).",
            retry_after=parse_retry_after(lower_headers.get("retry-after")),
            status_code=status_code,
            body=text,
        )
    return BackendError(f"HTTP {status_code}: {text}", status_code=status_code, body=text)
